import { useLayoutEffect, useState } from 'react';

/**
 * @param textRef - The reference attach to the text ellipsis component
 * @param itemName - The legend item name without cropping.
 * @returns true or false depending whether name is truncated or not.
 */
export const useLegendItemTruncation = (
  textRef: React.RefObject<HTMLSpanElement>,
  itemName: string,
): boolean => {
  const [isTruncated, setIsTruncated] = useState(false);

  useLayoutEffect(() => {
    if (textRef.current) {
      const observer = new MutationObserver((mutations) => {
        const [textMutation] = mutations ?? [];

        if (textMutation && textMutation.target instanceof HTMLSpanElement) {
          const text = textMutation.target.innerText;
          setIsTruncated(text.length < itemName.length);
        }
      });

      observer.observe(textRef.current, {
        characterData: true,
        childList: true,
        subtree: true,
      });

      const firstChild = textRef.current.firstChild;

      if (
        firstChild &&
        firstChild instanceof HTMLSpanElement &&
        firstChild.innerText
      ) {
        setIsTruncated(firstChild.innerText.length < itemName.length);
      }

      return () => observer.disconnect();
    }
  }, [itemName, textRef]);

  return isTruncated;
};
